package vmcompat;
import org.lwjgl.*;import org.lwjgl.glfw.*;import org.lwjgl.opengl.*;import java.nio.*;
/** Pixels from the production adapters, no game main or alternate renderer. */
public final class StorageBuffersTests {
 static void check(boolean b,String text){if(!b)throw new AssertionError(text+" / GL="+GL11.glGetError());}
 static int program(String fragment){String vs="#version 330\nvoid main(){vec2 p=vec2((gl_VertexID<<1)&2,gl_VertexID&2);gl_Position=vec4(p*2-1,0,1);}";int v=GL20.glCreateShader(GL20.GL_VERTEX_SHADER),f=GL20.glCreateShader(GL20.GL_FRAGMENT_SHADER),p=Shaders.glCreateProgram();Shaders.vpSource(v,vs);Shaders.vpSource(f,fragment);Shaders.glCompileShader(v);Shaders.glCompileShader(f);check(GL20.glGetShaderi(f,GL20.GL_COMPILE_STATUS)!=0,GL20.glGetShaderInfoLog(f));Shaders.glAttachShader(p,v);Shaders.glAttachShader(p,f);Shaders.glLinkProgram(p);check(GL20.glGetProgrami(p,GL20.GL_LINK_STATUS)!=0,GL20.glGetProgramInfoLog(p));GL20.glDeleteShader(v);GL20.glDeleteShader(f);return p;}
 static float pixel(){Draws.glDrawArrays(GL11.GL_TRIANGLES,0,3);FloatBuffer b=BufferUtils.createFloatBuffer(4);GL11.glReadPixels(8,8,1,1,GL11.GL_RGBA,GL11.GL_FLOAT,b);return b.get(0);}
 static void clean(String label){int error=GL11.glGetError();if(error!=0)throw new AssertionError(label+" GL=0x"+Integer.toHexString(error));}
 static void near(float value){check(Math.abs(pixel()-value)<.01,"storage pixel expected "+value);clean("pixel "+value);}
 public static void main(String[] args){check(GLFW.glfwInit(),"GLFW");GLFW.glfwWindowHint(GLFW.GLFW_VISIBLE,0);long w=Context.createWindow(16,16,"Read-only storage compatibility",0,0);Context.makeCurrent(w);var caps=Context.capabilities();GL11.glViewport(0,0,16,16);
  int p=program("#version 330\nlayout(std430) readonly buffer ModelDraws {vec4 uDraws[];};out vec4 c;void main(){c=uDraws[1];}");int loc=StorageBuffers.glGetProgramResourceIndex(p,StorageBuffers.BLOCK,"ModelDraws");check(loc>=0,"block metadata");StorageBuffers.glShaderStorageBlockBinding(p,loc,3);int b=Buffers.glGenBuffers();FloatBuffer data=BufferUtils.createFloatBuffer(8).put(new float[]{0,0,0,1,.25f,0,0,1});data.flip();Gl41.glNamedBufferStorage(b,data,0);Buffers.glBindBufferBase(StorageBuffers.TARGET,3,b);Shaders.glUseProgram(p);near(.25f);
  ModernGl.glNamedBufferSubData(b,16,new float[]{.5f,0,0,1});near(.5f);Gl41.glNamedBufferData(b,data,GL15.GL_DYNAMIC_DRAW);near(.25f);
  Buffers.glBindBufferRange(StorageBuffers.TARGET,3,b,0,32);near(.25f);Buffers.glBindBufferBase(StorageBuffers.TARGET,3,b);near(.25f);
  long other=Context.createWindow(16,16,"Shared storage consumer",0,w);Context.makeCurrent(other);Context.capabilities();GL11.glViewport(0,0,16,16);Buffers.glBindBufferBase(StorageBuffers.TARGET,3,b);Shaders.glUseProgram(p);near(.25f);clean("shared before destroy");Context.destroyWindow(other);Context.makeCurrent(w);GL.setCapabilities(caps);clean("return to primary");Shaders.glUseProgram(p);near(.25f);
  Buffers.glDeleteBuffers(b);b=Buffers.glGenBuffers();ModernGl.glNamedBufferStorage(b,new float[]{0,0,0,1,.75f,0,0,1},0);Buffers.glBindBufferBase(StorageBuffers.TARGET,3,b);near(.75f);Shaders.glDeleteProgram(p);clean("program delete");Buffers.glDeleteBuffers(b);clean("buffer delete");
  p=program("#version 330\n#define LAMP_SLICES 2\nlayout(std430) readonly buffer LampLists {uvec2 uLampSliceBits[LAMP_SLICES];uvec2 uLampTileBits[];};out vec4 c;void main(){c=vec4(float(uLampSliceBits[1].x+uLampTileBits[0].y)/255.,0,0,1);}");loc=StorageBuffers.glGetProgramResourceIndex(p,StorageBuffers.BLOCK,"LampLists");StorageBuffers.glShaderStorageBlockBinding(p,loc,4);b=Buffers.glGenBuffers();ModernGl.glNamedBufferStorage(b,new int[]{0,0,32,0,0,32},0);Buffers.glBindBufferBase(StorageBuffers.TARGET,4,b);Shaders.glUseProgram(p);near(64/255f);ModernGl.glClearNamedBufferData(b,GL30.GL_RG32UI,GL30.GL_RG_INTEGER,GL11.GL_UNSIGNED_INT,null);near(0);Shaders.glDeleteProgram(p);clean("program delete");Buffers.glDeleteBuffers(b);clean("buffer delete");
  p=program("#version 330\nlayout(std430) readonly buffer ReliefWalls {int uReliefWalls[];};layout(std430) readonly buffer LookRecords {uvec4 uLooks[];};out vec4 c;void main(){c=vec4(uReliefWalls[0]==-17 && uLooks[0].x==0xFFFFFFEFu ? .4:0.,0,0,1);}");
  for(String block:new String[]{"ReliefWalls","LookRecords"})StorageBuffers.glShaderStorageBlockBinding(p,StorageBuffers.glGetProgramResourceIndex(p,StorageBuffers.BLOCK,block),3);
  b=Buffers.glGenBuffers();ModernGl.glNamedBufferStorage(b,new int[]{-17,2,3,4},0);Buffers.glBindBufferBase(StorageBuffers.TARGET,3,b);Shaders.glUseProgram(p);near(.4f);Shaders.glDeleteProgram(p);Buffers.glDeleteBuffers(b);
  check(GL11.glGetError()==0,"final driver status");Context.destroyWindow(w);GLFW.glfwTerminate();System.out.println("PASS read-only std430 pixels, mutation, realloc, range/base, delete/recreate, shared-context and fixed+runtime arrays");
 }
}
